"Abstand Anfang / Ende":"始点/終点のオフセット",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"始点・終点の間隔を指定すると、フランジは部分フランジになります。スケッチ内のその他の閉じたプロファイルは、プレートの切り欠きになります。フランジ内の穴と窓は、エッジに沿った中心(曲線エッジでは円弧に沿った中心)、曲げ終端からの中心、サイズで指定し、展開図にも表示されます。曲線エッジが折れ目なしで隣のエッジにつながり、両方のフランジの曲げ角度が同じ場合、フランジは逃げ切り欠きなしでつながります。「スケッチから輪郭」はスケッチの閉じたプロファイルをフランジから切り抜きます。X軸はエッジに沿い、Y軸はフランジ内へ向かい、原点はエッジ始点の曲げ終端上にあります(移動可能)。",
