"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"削除したい面をすべて選択してください(ポケットなら壁と底面、穴なら壁面、フィレットなら丸み部分)。隣接する面は隙間を越えて延長されます。このステップはボディの変更に合わせて再計算されます。初回は大規模ジオメトリカーネルを読み込むため数秒かかります。",
