"Das Bild konnte nicht gelesen werden.":"画像を読み込めませんでした。",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"画像がテンプレートとして平面に配置されました。サイズ、位置、回転、不透明度はこのあとプロパティウィンドウで設定してください(例:既知の寸法に合わせて幅を設定)。",
"Das Ergebnis des Geometriekerns ist unlesbar":"ジオメトリカーネルの結果を読み取れません",
"Das Ergebnis konnte nicht geschrieben werden":"結果を書き込めませんでした",
"Das Maß muss größer als 0 sein.":"寸法は0より大きくする必要があります。",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"メッシュは三角形メッシュのままです(B-Repではありません)。編集はメッシュタブで行います:修復、削減、スムージング、平面カット …。製造の3Dフライス加工ストラテジーで直接加工できます。",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"メッシュには{0}個の三角形があります。それぞれがボディの面になるため、時間がかかり、ボディの動作も重くなります。先に「削減」を実行するほうが通常は適切です。\n\nそれでも変換しますか?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"メッシュが閉じていません。先に「修復」を実行してください。ボディには閉じたシェルが必要です。",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"メッシュの範囲はZが{0}~{1} mm、Xが{2}~{3} mm、Yが{4}~{5} mmです。直線からの偏差が公差未満の点は削除されます。",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"プロファイルは軸と交差してはいけません。スケッチ内の開いた線を軸として使用できます。",
"Das Profil mit den jetzigen Werten überschreiben":"現在の値でプロファイルを上書きします",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"プロファイルは線/ポリラインに沿ってスイープされます。プロファイルはパスの始点に対して垂直に描くのが最適です(例:プロファイルをXZ、パスをXYに)。",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"プロファイルはスケッチ平面から凸または凹にエンボス加工されます。",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"ストックは選択したボディを囲む直方体です(オフセットを加算)。",
"Das Setup hat keine Operationen.":"セットアップにオペレーションがありません。",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"工具は、中心が溝に沿って移動する円を描きながら加工します。全幅で切削に入ることがないため、大きな切込み深さが可能で、エンドミルと主軸にも優しい加工です。エンドミルは溝幅の約60 %が目安です。",
"Das Werkzeug schneidet die Fläche nicht":"ツールがサーフェスと交差していません",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"工具は指定された取り代に達するまで、選択した面に向かって切削します。",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"工具はドリルのように垂直に突入し、列ごとにモデルに取り代を加えた位置まで進みます。切削力は主軸方向に働くため、長い工具、深いキャビティ、剛性の低い機械に向いています。工具は中心刃付きである必要があります。{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"工具は指定された安全距離を考慮してこれらの面を回避します(クランプ、バイス)。",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"工具は近くの面を加工する間、これらの面を回避し、安全距離を保ちます。",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"1回目のEscはツールまたは選択の取り消しのみ行います。Escを余分に押してもスケッチは閉じません",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"これは穴ではありません(フィレットまたはピン)– 穴の内壁をクリックしてください。",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"これは穴(円筒面)ではありません – 穴の壁面をクリックしてください。",
"Das ist keine WerkFab-Design-Datei.":"WerkFabのテーマファイルではありません。",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"斜めのエッジではありません。面取りエッジの両端をクリックしてください。",
