"Datum/Uhrzeit":"日付／時刻",
"Deaktivieren":"無効化",
"Deckkraft":"不透明度",
"Deckkraft der Fenster":"ウィンドウの不透明度",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"直径が0または負になります。距離を小さくしてください",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"ねじ切りフライスは全面が材料の中を進みます。先にピンの周囲を削って空けてください(ピンの外側を、ねじ深さまで2D輪郭で加工)。",
"Der Körper hat auf dieser Ebene keinen Umriss.":"このボディには、この平面上の外形がありません。",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"ボディは表示用の三角形でメッシュとして取り込まれます。ボディ自体は残り、後からボディを変更してもメッシュは変わりません。",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"ボディは垂直な中心軸まわりにサンプリングされ、ホルダー輪郭(セグメント)としてドキュメントの工具ライブラリに保存されます。",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"ビューが回転する中心点(フリーオービット時)。「マウスポインタの下」は、回転を開始した位置のモデル上の点です。",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"半径は、選択した各エッジの始点から終点へ均等に変化します。どちらの端が始点かはエッジによって決まります。必要に応じて入れ替えてください。",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"面の縁は閉じたチェーンです。「連続」を選ぶと半径は周囲を一周する間に変化し、このオプションがない場合は各エッジごとに開始半径から終了半径へ変化します。",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"カットがどのボディにも当たっていません。材料は除去されません。",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"テキストはプログラムのこの位置にコメントとして入ります。",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"1つ目の距離は、より上(Z)を向いている面で測り、2つ目の距離または角度はもう一方の面に対して適用されます。「側を入れ替え」でこれが逆になります。接続する接線連続のエッジも含まれます。",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"選択したボディがストックです(例:鋳造または鍛造の素材)。ボディ自体は加工されません。",
"Der große Geometriekern ist noch nicht geladen":"フルジオメトリカーネルがまだ読み込まれていません",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"大規模ジオメトリカーネルを読み込み中です。この手順はまもなく自動的に再計算されます",
