"Dieses Gelenk bewegt sich mit dem gewählten (z. B. Zahnräder: Übersetzung = −Zähne₁/Zähne₂). Negative Werte drehen gegenläufig.":"このジョイントは選択したジョイントと連動して動きます(例:歯車の場合 ギア比=−歯数₁/歯数₂)。負の値では逆方向に回転します。",
