"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"回転: 要素を選択し、回転の中心点をクリックして、マウスで角度を指定します (プレビュー)。コピーとしても可能です",
