"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"追加した寸法と注記は、シート上でマウスによりドラッグできます(寸法線の間隔、引出線の角度、角度円弧の半径)。2つの角をクリックすると長さ寸法になります。平面図の円の縁をクリックすると直径(または半径)になります。角度は、まず頂点、続いて両方の辺上の点をそれぞれクリックします。面取りは、斜めのエッジの両端をクリックすると、たとえば2×45°になります。各寸法の後ろのテキスト欄には、±0,1、H7、4×などの追記を入力できます。",
