"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"丸いエンドミルは、内側コーナーごとに自身の半径分を残すため、角のある相手部品は収まりません。逃げ加工では、鋭い内側コーナーごとにコーナーへ短く進入して戻ります。{0}{1}",
