"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"まず移動するボディの面をクリックし、次にもう一方のボディの目標面をクリックします。1つ目のクリック位置が2つ目に重なり、面どうしが合わさるまで、ボディが回転・移動されます。",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"まず移動するボディのエッジをクリックし、次にもう一方のボディの目標エッジをクリックします。直線エッジは一致します(中点どうし)。円形エッジ(穴とピン)では軸が同じ向きに揃えられ、中心点が重ねられます。",
"Erst ein Setup anlegen.":"先にセットアップを作成してください。",
"Erst ein Setup mit Operationen anlegen.":"先にオペレーションを含むセットアップを作成してください。",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"先にスケッチまたは作業平面を選択してください。Ctrl+8でそれに正対します。",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"先に設計でボディを作成するか、メッシュ(STL)を挿入してください。",
"Erst einen Körper in KONSTRUKTION erstellen.":"先に設計でボディを作成してください。",
"Erst einen Namen für das Profil eingeben.":"先にプロファイル名を入力してください。",
"Erst in eine Vorlage klicken, dann den Platzhalter wählen":"先にテンプレート内をクリックしてから、プレースホルダを選択してください",
"Erste Ecke klicken, dann gegenüberliegende Ecke.":"最初の角をクリックし、次に対角の角をクリックします。",
