"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"ボディの面をクリックすると、その境界が輪郭としてスケッチに追加されます。エッジをクリックするとそのエッジだけが投影されます（円は円のまま）。投影されたジオメトリは紫色です。",
"Fläche ersetzen":"面を置換",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"面を置換: 平らな面を別の平面に移動します。ボディは大きくなるか短くなります",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"ウィンドウの背面の領域です。上で「カスタム」テーマを選択している場合に有効です",
