"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"部品端部の平面(二面、四角、六角)を、回転工具のエンドミルでZ方向に加工します。二面幅=平面から回転軸までの距離の2倍。XとCが同時に動きます(極座標補間、Fanuc G12.1)。ポストプロセッサにこのテンプレートがない場合は、短いX/Cステップが出力されます。",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"厚みを付ける面をクリックしてください（もう一度クリックすると解除）。",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"勾配を付ける面をクリックします(もう一度クリックすると解除)。",
