"Flächen im Modell":"モデル内の面",
"Flächen mit gemeinsamen Kanten werden zu einer verbunden. Ist die Hülle rundum geschlossen, entsteht ein Volumenkörper (danach normal weiterbearbeitbar). Lücken größer als die Toleranz bleiben offen.":"共通のエッジを持つサーフェスは1つに結合されます。シェルが全周で閉じている場合はソリッドボディになります(その後は通常どおり編集可能)。公差より大きい隙間は開いたままになります。",
