"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Fusion 360ファイル(.f3d)はAutodesk独自の非公開形式のため、読み込めません。\n\nFusion 360で「ファイル → エクスポート → STEP (.stp)」を選択し、そのファイルをここにインポートしてください。",
"Fusion-360-Postprozessor „{0}“ übernommen:\n\n• {1}":"Fusion 360のポストプロセッサ「{0}」を取り込みました：\n\n• {1}",
"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"上から届くすべての鋭い外側エッジをたどり、バリ取り深さ分だけ角を落とします。面取りカッタでは面取りとして(工具軸は垂直、先端はエッジの外側)、ボール/ロリポップエンドミルでは丸みを付けて加工します。",
