"Für Sweep wird ein Pfad gebraucht: offene Linie in einer Skizze (mit Enter beenden).":"スイープにはパスが必要です。スケッチ内の開いた線を描いてください(Enterで終了)。",
"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"タッチパッド用:スクロールでビューを移動、ピンチ(またはCtrl+マウスホイール)でズームします",
