"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"斜め方向には補助軸(2点、円柱、または2平面による)を作成してください。ここに方向として表示されます。",
