"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"スケッチ内でどのプロファイルにも属さない直線(補助線を含む)。曲げ:線は曲げ領域の中心で、そこでのスケッチがブランクになります。板の最も大きな部分はその場に残り、線の向こう側はフランジごと回転します。線は板全体に適用されます。ビード:線に沿ったリブで、断面も端部も丸く、板厚は変わりません。",
