"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"閉:隣り合う2つのエッジのフランジはコーナーの二等分線まで伸び、そこに隙間を残します。コーナーリリーフは曲げ領域が交差する位置(展開図および曲げ後の部品)に配置されます。曲線エッジ上のフランジも、実際のコーナーでは留め継ぎ(ミター)で切断されます(その部分にコーナーリリーフはありません)。",
