"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"板材1枚につき1ファイルです。経路は外形の隣、端材側に、カーフ幅の半分(フライス加工ではカッターの半分)だけずらして通ります。切り抜きは各部品の外形より先に加工され、各輪郭は端材からのリードインで始まります。オンはM3(レーザー:M3 S…)、オフはM5、ピアス時間はG4で出力します。ワーク原点は板材の左下隅で、フライス加工ではZ0が板の上面です。使用前に、機械上またはNCシミュレーターでプログラムを確認してください。",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"軸ごとに個別に:エッジ、頂点、面、または穴をクリックしてください。未設定の軸はストック点から取得されます。",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"各オペレーションをプログラム末尾のサブプログラム（LBL）にし、CALL LBLで呼び出します",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"スケッチ内のすべての円が穴の中心になります。穴はスケッチの法線と逆方向(材料の内側)にあけられます。",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"スケッチ内のすべての円が中心(スケッチ座標)を中心に回転しながら繰り返されます。ピッチ円半径の距離にある円は穴の円周配置になります。",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"スケッチ内のすべての円がグリッドになります。スケッチのXおよびY方向の間隔を指定します(負の値も可)。",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"次に2つ目の辺上の点を選択してください。",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"各方向を一度ずつ限界まで動かしてください:スライド、引く、押す、傾ける、ひねる(10秒) …",
"Jetzt laden":"今すぐダウンロード",
"Jetzt nach Updates suchen":"今すぐアップデートを確認",
"K-Faktor":"Kファクター",
"K-Faktor {0} liegt außerhalb des üblichen Bereichs 0,25 … 0,5 – der Zuschnitt weicht dann meist vom gebogenen Teil ab.":"Kファクター{0}が通常の範囲0,25~0,5を外れています。この場合、切断形状は曲げ後の部品とずれることがほとんどです。",
