"Kalibrieren abgebrochen.":"校正を中止しました。",
"Kalibrieren …":"校正 …",
"Kalibrieren: einen Abstand größer als 0 angeben.":"校正:0より大きい距離を指定してください。",
"Kalibrieren: ersten Punkt im Bild anklicken (Esc bricht ab).":"校正:画像上の1点目をクリックしてください(Escで中止)。",
"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"校正:2点間の実際の距離(mm)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"校正:距離が既知の2点を画像上でクリックし、実際の距離を入力してください。画像が正しいスケールになります。",
"Kalibrieren: zweiten Punkt im Bild anklicken (Esc bricht ab).":"校正:画像上の2点目をクリックしてください(Escで中止)。",
