"Kante am bewegten Körper gewählt":"移動するボディのエッジを選択済み",
"Kante im Blatt anklicken …":"シート上のエッジをクリック …",
"Kante projiziert":"エッジを投影しました",
"Kante {0} (Bogen R{1}, {2} mm)":"エッジ {0}(円弧 R{1}、{2} mm)",
"Kante {0} (Kreis R{1}, {2} mm)":"エッジ {0}(円 R{1}、{2} mm)",
"Kante {0} ({1} mm)":"エッジ {0} ({1} mm)",
"Kante {0} ist zu kurz für eine Lasche":"エッジ {0} はフランジには短すぎます",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"エッジ{0}:180°を超える曲げ角度は製作できません。",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"エッジ {0}:曲線エッジ上のフランジです。成形時にその縁が {1} % 圧縮されます(しわの恐れ)。この部分のブランクは近似です。",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"エッジ {0}:曲線エッジ上のフランジです。成形時にその縁が {1} % 伸びます(割れの恐れ)。この部分のブランクは近似です。",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"エッジ {0}:フランジ寸法 {1} mmが曲げ({2} mm)より小さくなっています",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"エッジ {0}:円弧がこのフランジには小さすぎます",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"エッジ{0}:オフセットによりフランジが残りません。",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"エッジ{0}:フランジが曲げ線と交差しています。「始点・終点の間隔」で曲げの手前で終わらせてください",
"Kante {0}: die Lasche liegt in einer Biegezone":"エッジ{0}:フランジが曲げ領域にあります",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"エッジ {0}:存在しないフランジに属する切り欠きがあります。",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"エッジ {0}:フランジの切り欠きが曲げから {1} mm の位置にあります(板厚の2倍未満)。曲げ時に変形します。",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"エッジ{0}:切り欠きが曲げから{1} mmの位置にあります(板厚の2倍未満)。曲げ加工時に変形します。",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"エッジ {0}:切り欠きがフランジからはみ出しています。",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"エッジ{0}{1}:フランジ{2} mmが板厚の2倍より短く、プレスブレーキではほとんど曲げられません。",
"Kanten":"エッジ",
"Kanten (Geraden deckungsgleich, Kreise mittig)":"エッジ(直線は一致、円は同心)",
"Kanten anklicken (erneut klicken entfernt).":"エッジをクリックしてください（もう一度クリックすると解除）。",
"Kanten wählen":"エッジを選択",
"Kanten wählen, die einen geschlossenen Rand bilden":"閉じた境界を形成するエッジを選択",
"Kantenglättung":"アンチエイリアス",
"Kantenhöhe":"エッジ高さ",
"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"キャップから手を離し、「ゼロ点をキャリブレーション」を選びます。その後、各方向を試してください。バーが動き、静止時は灰色の不感帯内にとどまれば正常です。",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"キャップをスライド=パン、押す/引く=ズーム、傾ける/ひねる=モデルを回転。スケッチではパンとズームのみ使用できます。SpaceMouse Pro/Enterprise:T、F、R=上面、正面、右側面ビュー。反応がない場合は、3Dconnexionドライバを一度終了してから再接続してください。",
