"Kein Restmaterial – der vorige Fräser erreicht schon alles":"残り材料はありません。前のフライスですべて加工済みです",
"Kein Rohteil im aktiven Setup – erst ein Modell und Operationen anlegen.":"アクティブなセットアップにストックがありません。先にモデルとオペレーションを作成してください。",
