"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"{0}点の輪郭 – Okuma: G85 (LAP)と輪郭G81…G80、Fanuc: G71 P…Q…。制御装置は独自の切込み配分で荒加工します。ここでのシミュレーションはWerkFabのパスです。",
"Kontur zum Freifräsen davor anlegen":"前に逃げ加工用の輪郭を作成",
