"Konturen außen und innen":"外側と内側の輪郭",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"輪郭は暗い領域の縁に沿います。中心線は線の中央を通るため、彫刻や線画に適しています。「直線、円弧、円」は直線のエッジ、鋭い角、丸み、円を認識します。「ポリライン」は画像を点ごとにたどります。スケールは必要に応じて、このあと「テンプレートを校正」または「スケール」で調整してください。",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"制御装置で工具径補正（RL/RR）を行う輪郭は、APPR/DEPでアプローチ・退出します。補助点と補正は制御装置が自動計算します",
