"Kurven":"曲線",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"端面(回転軸に直交)上のスケッチの曲線を、Z方向の回転工具で加工します(XとCが同時に動きます。Fanuc: 極座標補間G12.1)。開いた曲線は往復で加工されます。深さは端面から。",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"回転軸に沿って置かれたスケッチの曲線を外周に巻き付け、軸に向いた回転工具で加工します(ZとCが同時に動きます。Fanuc: 円筒補間G7.1)。スケッチ平面が輪郭の位置する角度を決め、スケッチ内の水平線分は部品を巡る円弧になります。深さは外径から。",
"Kurzbefehl":"ショートカット",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"短い移動(保持距離まで)では、工具は退避高さまで上がらず、下げたまま移行送り速度で動きます。干渉チェックは行われないため、小さな値にしてください。",
