"Mehrere Schlichtdurchgänge":"複数回の仕上げパス",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"連続する複数のエッジは1本の経路として扱われます。半径はチェーンの始点から終点まで変化し、制御点はチェーン全長に対する%で指定します。これは大規模ジオメトリカーネルが計算します。",
