"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"制御点を使うと、半径は指定した値を通って変化します(位置はエッジ長に対する%)。これは大規模ジオメトリカーネルが計算します。初回は読み込みに数秒かかります。",
"Mit dem 3D-Taster kann nicht zerspant werden":"3Dプローブでは切削できません",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"完成品と比較：緑＝寸法どおり、青＝残り材料、赤＝削りすぎ",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"輪郭の横にカーソルを移動（側で方向が決まります） · Escで終了",
"Mit diesem Werkzeug kann nicht gefräst werden":"この工具ではフライス加工できません",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"タップでは「タップ加工」サイクルのみ使用してください。穴あけサイクルではタップが折れます",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"複数回の切込みでは、ねじ深さをほぼ同じ除去量の段階に分けて加工します。小径のねじ切りフライスや硬い材料に優しい方法です。スプリングパスは、最後のパスを切込みなしでもう一度たどります。",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"NCプログラムで「穴あけサイクル」を選ぶと制御装置サイクルが出力され(G81–G86、Heidenhain CYCL 200–207、Sinumerik CYCLE81–85)、選ばない場合は個別の動作として展開されます。",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"「元を残す」を選ぶと、元と鏡像が1つのメッシュになり、ミラー平面上の点が接続されます。これにより、開いた半分が閉じた部品になります。",
