"Nichts getroffen – Kante, Ecke, Fläche oder Bohrung anklicken.":"何も選択されませんでした。エッジ、頂点、面、または穴をクリックしてください。",
"Nichts getroffen – auf das Modell klicken.":"何も選択されませんでした。モデル上をクリックしてください。",
"Nichts gewählt – „Auswählen“ und im Modell anklicken.":"未選択です。「選択」を押してモデル上をクリックしてください。",
"Nichts gewählt – „Auswählen“, dann Flächen oder Kanten im Modell anklicken.":"未選択です。「選択」を押してから、モデル上の面またはエッジをクリックしてください。",
"Nichts geändert: Die Nachbarflächen schließen diese Lücke nicht – zusammengehörige Flächen gemeinsam wählen (z. B. Wand und Boden einer Tasche)":"変更はありません。隣接する面ではこの隙間を閉じられません。関連する面をまとめて選択してください(例:ポケットの壁と底面)",
"Nichts zu schruppen":"荒加工する箇所がありません",
"Nichts zum Umbenennen gewählt.":"名前を変更するものが選択されていません。",
"Niedrig (0,05 mm)":"低（0,05 mm）",
"Noch kein Dreh-Setup: „Neues Setup“ → Bearbeitung „Drehen“ wählen.":"旋削セットアップがありません。「新規セットアップ」→加工「旋削」を選択してください。",
"Noch kein Fräs-Setup vorhanden.":"フライス加工のセットアップがありません。",
"Noch kein Körper gewählt – bis dahin gilt die relative Quadergröße.":"ボディが未選択です。それまでは相対的な直方体サイズが適用されます。",
"Noch kein Körper vorhanden – erst in KONSTRUKTION modellieren.":"ボディがまだありません。まず「設計」でモデリングしてください。",
"Noch keine Designs gespeichert.":"保存されたデザインはまだありません。",
"Noch keine Kommentare. Mit + Notizen zum Design festhalten.":"コメントはまだありません。+でデザインにメモを残せます。",
"Noch keine Operation":"オペレーションがありません",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"テンプレートはまだありません。テンプレートは、ストラテジーをすべての設定（工具、切削データ、高さ、パス数、リンク）とともに保存し、他のセットアップや設計で再利用できるようにします。",
"Noch keine Werkzeuge im Dokument.":"ドキュメントにまだ工具がありません。",
"Noch keine. Geometrie wählen und oben unter ABHÄNGIGKEITEN ein Werkzeug anklicken.":"まだありません。ジオメトリを選択し、上の拘束の項目でツールをクリックしてください。",
