"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"制御装置サイクルでは外側輪郭(ボス)のみ使用できます",
"Nur Durchmesser (Form wie dieses Werkzeug)":"直径のみ(形状はこの工具と同じ)",
"Nur Innenkonturen (Öffnungen)":"内側の輪郭のみ(開口部)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"制御装置サイクルでは長方形と円形のポケットのみ使用できます",
"Nur Skizze":"スケッチのみ",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"大きいカッターが隅に残した部分のみを加工します。",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"大きいカッターが届かなかった輪郭の部分(内側の隅、狭い箇所)のみをなぞります。アプローチ/退出円弧、タブ、仕上げパスはなく、補正はコンピュータ側で行います。",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"基準工具が届かなかった箇所のみ加工します。平坦部は平行、急斜面は等高線で行います。リストの工具を選ぶとその形状も考慮されます。たとえばラジアスエンドミルが隅R部に残す部分です。",
"Nur ebene Flächen können als Skizzenebene dienen.":"スケッチ平面にできるのは平らな面だけです。",
"Nur ebene Flächen können extrudiert werden":"押し出しできるのは平面のみです",
"Nur ebene Flächen lassen sich ersetzen":"置き換えられるのは平面のみです",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"オフセットできるのは平面と円筒面（穴、ボス）のみです",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"工具に向かって上を向いた平らな面のみ(このセットアップでは水平)。",
"Nur für Außen-Drehmeißel":"外径用旋削工具専用です",
"Nur in Operationen verwendete":"オペレーションで使用中のみ",
"Nur in diesem Projekt":"このプロジェクトのみ",
"Nur mit Korrektur „Im Rechner“.":"補正が「コンピュータ内」の場合のみ。",
"Nur stärkste Achse":"最大の軸のみ",
"Nut":"溝",
"Nut angetrieben":"回転工具による溝加工",
"Nut angetrieben (C-Achse)":"回転工具による溝加工（C軸）",
"Nut liegt nicht am Teil":"溝が部品上にありません",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"回転軸に沿った溝(例:キー溝)を、軸に向いた回転工具で加工します。主軸が部品をC軸として保持します。溝幅=エンドミルØ。開始/終点Zはモデル座標のZ。溝が端面まで達する場合、エンドミルは前方から進入し、そうでなければ開始位置で突入します。深さは外径から。",
"Nutbreite bei Linien":"線の場合の溝幅",
