"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"開いたエッジは赤で表示されます。「修復」で穴を塞ぎます。",
"Offene Linie in einer Skizze wählen":"スケッチ内の開いた線を選択",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"開いた曲線または閉じた曲線がスケッチに垂直に押し出されます。結果はサーフェス(厚さのない壁)です。「厚み付け」または「縫合」でソリッドにできます。",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"開いた曲線または閉じた曲線が軸まわりに回転されます。結果はサーフェスであり、ソリッドではありません。",
"Ohne eigene Taste gilt der Standard „{0}“.":"独自のキーがない場合は、標準の「{0}」が使用されます。",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"「モデル化」なしの場合、ねじは表示のみです(高速)。モデル化すると、ねじ形状が実際に切り取られます(例:3Dプリント用)。M8の下穴=Ø6,8。",
"Okuma OSP Drehen":"Okuma OSP旋削",
"Okuma OSP-M Fräsen":"Okuma OSP-Mフライス",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP：G28/G53では機械座標に移動しません（G53は工具長補正を解除します）。安全高さへ退避し、XY基準位置への移動は出力しません",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP：スムージング機能は出力しません（G5.1はFanuc用）。Hi-Cut／Super-NURBSは機械側で設定してください",
