"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade:すべての機能。Rustカーネル(truck、実験的):基本形状、押し出し、回転、穴、パターン、ミラー、移動、スケール、結合、STEPエクスポート。その他のフィーチャは「未対応」と表示されます。",
