"Prägung {0}: lässt sich so nicht formen":"エンボス{0}:この形状では成形できません",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"エンボス{0}:{1} mmは板厚の3倍を超えています。壁が垂直だと板が割れます。",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt. Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"エンボス:輪郭は切り抜かれず、指定の高さだけ板から押し出されます。皿絞り:丸い穴の縁を90°の円すい状に押し込みます。薄板への皿ねじ用です(− 下:ねじは上から)。",
