"Rechteck-/Kreistasche erkannt ({0}) – Heidenhain: CYCL DEF 251/252 an der Taschenmitte. Die Steuerung fräst mit ihrer eigenen Strategie; Simulation und Bahn hier sind die WerkFab-Bahn.":"角形/円形ポケットを検出しました({0})– Heidenhain: ポケット中心でCYCL DEF 251/252。制御装置は独自の方式で加工します。ここでのシミュレーションとパスはWerkFabのパスです。",
