"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"旋盤軸に沿って配置されたスケッチの閉じた輪郭から、外周上にポケットを作成します(内側の輪郭は島として残ります)。スケッチは直径に巻き付けられ、軸方向を向いた駆動式エンドミルが内側から外側へ加工します(ZとCが同時に動作、Fanuc:円筒補間G7.1)。カッターは最も内側のリングに沿ってランプで切り込みます。",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"スケッチの閉じた輪郭から、端面にポケットを加工します(内側の輪郭はアイランドとして残ります)。回転工具のエンドミルをZ方向に使用します。内側から外側へ除去し、エンドミルは最も内側のパスに沿ったランプで進入し、1つのレベル内では下がったままです。XとCが同時に動きます(Fanuc: 極座標補間G12.1)。深さは端面から。",
