"Vernetzung fehlgeschlagen:":"メッシュ化に失敗しました：",
"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"2つの閉じたメッシュを実際に演算します。内側にある面は消え、交差エッジは再メッシュされます。演算は2つのメッシュが接する可能性のある範囲だけで行われるため、大きなメッシュに小さな操作を加える場合は高速です。大きな2つのメッシュが完全に重なる場合は、先に「リダクション」を実行してください。",
