"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"「入れ子にする」は、ブランクを隣のブランクの隙間や凹部、およびその切り欠きの中に配置します(90°回転なしの場合は180°反転のみ)。間隔が指定値を下回ることはありません。チェックを外すと、外接する長方形を基準に列状に配置されます。「スケッチ+ボディ」を選ぶと板厚の平らなボディが作成され、製造で2D輪郭により切り抜けます。",
